-- CNG_CYLINDER_INSPECTION, a car document beside the revisione: the
-- requalification of the CNG (metano) cylinders of a car (DM 13 maggio 2022
-- n. 144: every 4 years for UNECE R110 cylinders, every 5 for national DGM
-- ones). The workshop applies a label on the car (Comitato Fondo Bombole
-- Metano) with the plate, the month applied and, per cylinder, its litres,
-- maker, serial number and due month (scadenza); svc-cars reads it as a
-- series of the car, with its renewal and the car's CNG section.
-- Up to four cylinders, numbered as the label's rows (cylinder_1_...).
-- It sits under CAR_DOCUMENT, where VEHICLE_INSPECTION sits. A category with
-- the same id is kept as it is; when one of yours already has the title "CNG
-- cylinder inspection", this one is added as "CNG cylinder inspection
-- (bombole metano)" instead (titles are unique).
-- Data only. Rollback: drizzle/rollback/0032_cng_cylinder_category.down.sql.
WITH inserted AS (
  INSERT INTO "ingestion"."document_categories" ("id", "title", "description", "template_json", "dimension", "parent_id")
  SELECT 'CNG_CYLINDER_INSPECTION',
         CASE WHEN EXISTS (SELECT 1 FROM "ingestion"."document_categories" WHERE lower("title") = 'cng cylinder inspection')
              THEN 'CNG cylinder inspection (bombole metano)' ELSE 'CNG cylinder inspection' END,
         'The label (cartellino) of a requalification of the CNG (metano) cylinders of a car, applied by the workshop on the car (Comitato Fondo Bombole Metano), or the workshop''s certificate or invoice for it: plate, month applied, each cylinder''s litres, maker, serial number and due month (scadenza), ECE R110 or national approval. Not the car''s own revisione.',
         '{"fields": [{"key": "registration_number", "label": "Number plate", "type": "string", "description": "Targa written on the label, without spaces, upper-case (AB123CD)", "required": true}, {"key": "vin", "label": "VIN", "type": "string", "description": "Numero di telaio, if printed", "required": false}, {"key": "applied_month", "label": "Requalified in", "type": "string", "description": "Month of the requalification as YYYY-MM: ''Applicata il'' on the label (luglio 2023 is 2023-07), or the date of the workshop''s certificate", "required": true, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "workshop", "label": "Workshop", "type": "string", "description": "Officina or centre that requalified the cylinders, from its stamp (timbro), name only", "required": false}, {"key": "label_number", "label": "Label number", "type": "string", "description": "Numero progressivo of the label (Comitato Fondo Bombole Metano), or the number of the certificate", "required": false}, {"key": "approval", "label": "Approval", "type": "enum", "description": "r110 when the label or cylinder says ECE R110 (or R 110, CNG-1..CNG-4); national for a DGM national approval; null when not printed", "required": false, "options": ["r110", "national"]}, {"key": "cylinder_type", "label": "Cylinder type", "type": "enum", "description": "R110 type when printed: CNG1 steel, CNG2 and CNG3 hoop or fully wrapped metal liner, CNG4 all-composite", "required": false, "options": ["CNG1", "CNG2", "CNG3", "CNG4"]}, {"key": "cylinder_1_litres", "label": "Cylinder 1: litres", "type": "number", "description": "Row 1 of the label: litri (water capacity), Italian decimals (18,1 is 18.1)", "required": false, "unit": "l"}, {"key": "cylinder_1_make", "label": "Cylinder 1: maker", "type": "string", "description": "Row 1 of the label: marca (FABER, DALMINE...)", "required": false}, {"key": "cylinder_1_serial", "label": "Cylinder 1: serial number", "type": "string", "description": "Row 1 of the label: matricola, as written (12/3456/055)", "required": false}, {"key": "cylinder_1_due_month", "label": "Cylinder 1: due", "type": "string", "description": "Row 1 of the label: scadenza as YYYY-MM (07/2027 is 2027-07)", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "cylinder_2_litres", "label": "Cylinder 2: litres", "type": "number", "description": "Row 2 of the label: litri (water capacity), Italian decimals (18,1 is 18.1)", "required": false, "unit": "l"}, {"key": "cylinder_2_make", "label": "Cylinder 2: maker", "type": "string", "description": "Row 2 of the label: marca (FABER, DALMINE...)", "required": false}, {"key": "cylinder_2_serial", "label": "Cylinder 2: serial number", "type": "string", "description": "Row 2 of the label: matricola, as written (12/3456/055)", "required": false}, {"key": "cylinder_2_due_month", "label": "Cylinder 2: due", "type": "string", "description": "Row 2 of the label: scadenza as YYYY-MM (07/2027 is 2027-07)", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "cylinder_3_litres", "label": "Cylinder 3: litres", "type": "number", "description": "Row 3 of the label: litri (water capacity), Italian decimals (18,1 is 18.1)", "required": false, "unit": "l"}, {"key": "cylinder_3_make", "label": "Cylinder 3: maker", "type": "string", "description": "Row 3 of the label: marca (FABER, DALMINE...)", "required": false}, {"key": "cylinder_3_serial", "label": "Cylinder 3: serial number", "type": "string", "description": "Row 3 of the label: matricola, as written (12/3456/055)", "required": false}, {"key": "cylinder_3_due_month", "label": "Cylinder 3: due", "type": "string", "description": "Row 3 of the label: scadenza as YYYY-MM (07/2027 is 2027-07)", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "cylinder_4_litres", "label": "Cylinder 4: litres", "type": "number", "description": "Row 4 of the label: litri (water capacity), Italian decimals (18,1 is 18.1)", "required": false, "unit": "l"}, {"key": "cylinder_4_make", "label": "Cylinder 4: maker", "type": "string", "description": "Row 4 of the label: marca (FABER, DALMINE...)", "required": false}, {"key": "cylinder_4_serial", "label": "Cylinder 4: serial number", "type": "string", "description": "Row 4 of the label: matricola, as written (12/3456/055)", "required": false}, {"key": "cylinder_4_due_month", "label": "Cylinder 4: due", "type": "string", "description": "Row 4 of the label: scadenza as YYYY-MM (07/2027 is 2027-07)", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "next_due_month", "label": "Next requalification by", "type": "string", "description": "The earliest scadenza on the label as YYYY-MM: the month the cylinders are due again", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "end_of_life_month", "label": "End of life", "type": "string", "description": "Only when printed: the month the cylinders may no longer be used (DO NOT USE AFTER, fine vita), YYYY-MM", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "manufacture_month", "label": "Manufactured", "type": "string", "description": "Only when printed as a date: month the cylinders were made, YYYY-MM. Never guess it from the serial number", "required": false, "pattern": "^[0-9]{4}-(0[1-9]|1[0-2])$"}, {"key": "total_litres", "label": "Total litres", "type": "number", "description": "tot lt.: the litres of all cylinders", "required": false, "unit": "l"}, {"key": "total_amount", "label": "Total paid", "type": "amount", "description": "Amount paid, only when the document is an invoice or receipt", "required": false}]}'::jsonb,
         COALESCE((SELECT "dimension" FROM "ingestion"."document_categories" WHERE "id" = 'VEHICLE_INSPECTION'), 'DOCUMENT_TYPE'),
         (SELECT "parent_id" FROM "ingestion"."document_categories" WHERE "id" = 'VEHICLE_INSPECTION')
  ON CONFLICT DO NOTHING
  RETURNING "id", "title", "parent_id", "dimension"
)
-- Modules that keep their own copy of the categories (review inbox, Cars) learn it from category.changed@1.
INSERT INTO "ingestion"."outbox" (event_type, payload)
SELECT 'category.changed@1',
       jsonb_build_object(
         'id', i.id,
         'title', i.title,
         'parentId', i.parent_id,
         'dimension', i.dimension,
         'deleted', false,
         'changedAt', to_char(now() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
       )
  FROM inserted i;
